def check_sequence_correct_v3(a):
    for p in range(len(a) - 1):
        idx1 = a[p]
        if idx1 >= len(a): return False
        idx2 = a[idx1]
        if idx2 >= len(a): return False
        # a[a[a[p]]] is a[idx2]
        if a[idx2] != a[p+1] + 1:
            return False
    return True

a = [i + 1 for i in range(11)]
print(f"a_p = p+1: {check_sequence_correct_v3(a)}")

import itertools
for a in itertools.product(range(10), repeat=8):
    if check_sequence_correct_v3(a):
        if any(a[i] != i + 1 for i in range(8)):
            print(f"Found another: {a}")

